<template>
    <button type="button" @click="toGameSelect">
        <div class="img" :style="imageBg" />
        <div class="text">
            <p class="name ellipsis">{{ activeGame.displayName }}</p>
            <p class="call-to-action">Change game</p>
        </div>
    </button>
</template>

<script lang="ts" setup>
import ManagerSettings from "@/r2modmanPlus/src/r2mm/manager/ManagerSettings";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {computed} from "vue";
import {State} from "@/overwolf/store";
import ProtocolProvider from "@/r2modmanPlus/src/providers/generic/protocol/ProtocolProvider";
import {useRouter} from "vue-router";

const store = getStore<State>();
const router = useRouter();

const activeGame = computed(() => store.state.activeGame);

const imageBg = computed(() => {
  const publicAssetUrl = ProtocolProvider.getPublicAssetUrl(`/images/game_selection/${activeGame.value.gameImage}`);
  return {backgroundImage: `url('${publicAssetUrl}')`}
});

async function toGameSelect() {
    await ManagerSettings.resetDefaults();
    await router.push({name: "index"});
}
</script>

<style lang="scss" scoped>
button {
    display: flex;
    gap: 10px;
    margin-bottom: 12px;
    border: none;
    border-radius: 4px;
    padding: 0;
    text-align: left;
    background-color: var(--TSDC-bg-dark);

    &:hover {
        cursor: pointer;
        background-color: rgba(0, 0, 0, 0.08);

        .img {
            filter: brightness(0.9);
        }

        .call-to-action {
            color: var(--TSSC-accent-secondary-default);
        }
    }
}

.img {
    flex: 0 0 40px;
    height: 40px;
    border-radius: 4px;
    background-size: cover;
    background-position: center;
}

.text {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 4px;
    height: 100%;
    min-width: 0;
    font-weight: 700;
}

.name {
    font-size: 1rem;
    color: var(--TSSC-LM-text);

    // Overflow: hidden set by .ellipsis would cause letter descenders
    // to clip. Adjust line-height to prevent the clipping and margins
    // to prevent the line-height change from moving the element.
    line-height: 1.25;
    margin: -2px 0;
}

.call-to-action {
    white-space: nowrap;
    font-size: 11px;
    line-height: 1;
    color: var(--TSSC-LM-text-ternary);
}

.html--dark {
    button:hover {
        background-color: var(--TSDC-bg-light);

        .img {
            filter: brightness(1.1);
        }
    }

    .name { color: var(--TSSC-text-link-hover); }
    .call-to-action { color: var(--TSSC-text-secondary); }
}
</style>
