<template>
    <nav :class="`non-selectable ${collapsed ? 'collapsed' : ''}`">
        <GameSelection v-tooltip="tooltip('Change game')" />

        <ul>
            <li>
                <SidebarLink
                    icon="fa-box-open"
                    routeName="manager.installed"
                    label="My mods"
                    :badgeCount="myModCount"
                    v-tooltip="tooltip('My mods')"
                />
            </li>
            <li>
                <SidebarLink
                    icon="fa-search"
                    routeName="manager.online"
                    label="Get mods"
                    :badgeCount="onlineModCount"
                    v-tooltip="tooltip('Get mods')"
                />
            </li>
            <li>
                <SidebarLink
                    icon="fa-download"
                    routeName="downloads"
                    label="Downloads"
                    :badgeCount="store.getters['download/profileActiveDownloadCount'] || 0"
                    v-tooltip="tooltip('This profile\'s downloads')"
                />
            </li>
            <li class="spacer">
                <SidebarLink
                    icon="fa-edit"
                    routeName="config-editor"
                    label="Edit config"
                    v-tooltip="tooltip('Edit config')"
                />
            </li>
            <li>
                <SidebarLink
                    icon="fa-cog"
                    routeName="manager.settings"
                    label="Settings"
                    v-tooltip="tooltip('Settings')"
                />
            </li>
        </ul>

        <ul class="bottom">
            <li>
                <SidebarLink
                    icon="fa-question-circle"
                    routeName="help"
                    label="Help"
                    v-tooltip="tooltip('Help')"
                />
            </li>
            <li>
                <button
                    type="button"
                    @click="toggleCollapse()"
                    class="toggle"
                    v-tooltip="tooltip('Expand menu')"
                >
                    <font-awesome-icon icon="fa-regular fa-arrow-right-from-line" fixedWidth />
                    <span>Collapse menu</span>
                </button>
            </li>
        </ul>
    </nav>
</template>

<script lang="ts" setup>
import GameSelection from "@/overwolf/components/manager/GameSelection.vue";
import SidebarLink from "@/overwolf/components/manager/SidebarLink.vue";
import {StorageManager} from "@/overwolf/utils/storage";
import {computed, onMounted, ref} from "vue";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {State} from "@/overwolf/store";

const store = getStore<State>();

const storage = new StorageManager("sidebar");

const collapsed = ref<boolean>(false);

const myModCount = computed<number>(() => store.state.profile.modList.length);

const onlineModCount = computed<number>(() =>
    store.state.modFilters.showDeprecatedPackages
      ? store.state.tsMods.mods.length
      : store.getters['tsMods/undeprecatedModCount']
);

function tooltip(content: string) {
    return {
        content,
        delay: { show: 400, hide: 0 },
        disabled: !collapsed.value,
        distance: 8,
        placement: "right",
    };
}

function toggleCollapse() {
    collapsed.value = !collapsed.value;
    storage.setBool("collapsed", collapsed.value);
}

onMounted(() => {
  collapsed.value = storage.getBool("collapsed") ?? false;
});
</script>

<style lang="scss" scoped>
nav {
    display: flex;
    flex-direction: column;
    width: 13.25rem;
    padding: 0.75rem 0.5rem 0.5rem 0.5rem;
    overflow: hidden;
    background-color: var(--TSDC-bg-dark);
    transition: width 0.2s ease-in-out;

    &.collapsed {
        width: 56px;

        .toggle svg {
            transform: rotate(0deg);
        }
    }
}

li {
    margin-bottom: 4px;
    &:last-of-type { margin-bottom: 0; }
    &.spacer { margin-top: 16px; }
}

.bottom {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    flex: 1;
}

.toggle {
    display: flex;
    align-items: center;
    gap: 20px;
    width: 100%;
    height: 40px;
    padding: 10px;
    border: none;
    border-radius: 4px;
    color: var(--TSDC-navitem-text);
    background-color: var(--TSDC-navitem-bg);
    cursor: pointer;

    &:hover {
        color: var(--TSDC-navitem-text-hover);
        background-color: var(--TSDC-navitem-bg-hover);
    }

    svg {
        flex: 0 0 18px;
        height: 18px;
        transition: transform 0.2s;
        transform: rotate(-180deg);
    }

    span {
        white-space: nowrap;  // To prevent multiple lines during expanding animation
        font-size: 14px;
        font-weight: 600;
        line-height: 1;
    }
}
</style>
