<template>
    <div class="launch-bar">
        <router-link :to="{name: 'profiles'}" class="profile">
            <p class="name ellipsis">{{ store.getters['profile/activeProfileName'] }}</p>
            <p class="call-to-action">Change profile</p>
        </router-link>

        <Button :onClick="shareProfile" :disabled="store.state.profileExport.isSharePending" class="ghost">
            <font-awesome-icon v-if="store.state.profileExport.isSharePending" icon="fa-regular fa-cog" fixedWidth spin />
            <font-awesome-icon v-else icon="fa-solid fa-share-alt" fixedWidth />
            Share
        </Button>

        <div :class="`launcher ${store.getters['subscription/showAdSidebar'] ? '' : 'right-padding'}`">
            <Button :onClick="() => launch(LaunchMode.VANILLA)" class="ghost">
                <font-awesome-icon icon="fa-regular fa-play-circle" />
                Vanilla
            </Button>
            <Button :onClick="() => launch(LaunchMode.MODDED)" class="cta2">
                <font-awesome-icon icon="fa-solid fa-play-circle" />
                Modded
            </Button>
        </div>
    </div>
</template>

<script lang="ts" setup>
import Button from "@/overwolf/components/TsButton.vue";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import Game from "@/r2modmanPlus/src/model/game/Game";
import Profile from "@/r2modmanPlus/src/model/Profile";
import {
  launch as launchGame,
  LaunchMode,
  linkProfileFiles,
  setGameDirIfUnset,
  throwIfNoGameDir
} from '@/r2modmanPlus/src/utils/LaunchUtils';
import {useRouter} from "vue-router";
import {sleep} from "@/r2modmanPlus/src/utils/Common";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {State} from "@/overwolf/store";
import Manager from "@/r2modmanPlus/src/pages/Manager.vue";

const store = getStore<State>();
const router = useRouter();

function getManagerFromRoute(): typeof Manager | undefined {
    // This is a bit of a hack, but a more proper solution would require
    // refactoring the profile export state management to a vuex store which
    // is a high complexity change & requires updates to r2modman.
    //
    // Notably the export-related success & error UIs are handled by the
    // Manager class, so even re-implementing the export call wouldn't
    // suffice.
    const managerRoute = router.currentRoute.value.matched.filter(x => x.name === "manager")[0];
    if (!managerRoute) return;
    return managerRoute.instances["default"] as typeof Manager | undefined;
}

async function launch(mode: LaunchMode) {
    try {
        const game: Game = store.state.activeGame;
        const profile: Profile = store.state.profile.activeProfile;

        await setGameDirIfUnset(game);
        await throwIfNoGameDir(game);

        if (mode === LaunchMode.MODDED) {
            await linkProfileFiles(game, profile.asImmutableProfile());
        }

        store.commit("openGameRunningModal");
        await launchGame(game, profile, mode);
    } catch (error) {
        store.commit("closeGameRunningModal");
        store.commit("error/handleError", R2Error.fromThrownValue(error));
    }
}

async function shareProfile() {
    let manager = getManagerFromRoute();
    if (!manager) {
        await router.push({name: "manager.installed"});
        await sleep(0); // We need to force a context swap so vue has
                        // time to instantiate the manager component.
        manager = getManagerFromRoute();
        if (!manager) return; // Technically shouldn't happen, still check
    }
    store.commit("profileExport/setIsSharePending", true);
    try {
        await store.dispatch("profileExport/exportProfileAsCode");
    } catch (e) {
        store.commit("error/handleError", R2Error.fromThrownValue(e));
    } finally {
        store.commit("profileExport/setIsSharePending", false);
    }
}
</script>

<style lang="scss" scoped>
.launch-bar {
    display: flex;
    gap: 0.5rem;
    width: 100%;
    padding: 0.75rem;
    background-color: var(--TSDC-bg-dark);
}

.profile {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 0.25rem;
    max-width: 12.25rem;
    padding: 0 0.625rem;
    border-radius: 0.25rem;
    font-weight: 700;

    .name {
        font-size: 1rem;
        color: var(--TSSC-LM-text);

        // Overflow: hidden set by .ellipsis would cause letter descenders
        // to clip. Adjust line-height to prevent the clipping and margins
        // to prevent the line-height change from moving the element.
        line-height: 1.25;
        margin: -2px 0;
    }

    .call-to-action {
        font-size: 0.6875rem;
        color: var(--TSSC-LM-text-ternary);
    }

    &:hover {
        background-color: rgba(0, 0, 0, 0.08);

        .call-to-action {
            color: var(--TSSC-accent-secondary-default);
        }
    }
}

.launcher {
    display: flex;
    gap: 0.5rem;
    margin-left: auto;
}

.right-padding {
    padding-right: 1rem;
}

.html--dark {
    .profile:hover { background-color: var(--TSDC-bg-light); }
    .name { color: var(--TSSC-text-link-hover); }
    .call-to-action { color: var(--TSSC-text-secondary); }
}
</style>
